// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;

    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(address depositor, uint256 amount) public {
        vm.assume(depositor != address(0));
        amount = bound(amount, 0, 1 ether);

        vm.deal(depositor, amount);

        if (amount > 0) {
            vm.prank(depositor);
            c.deposit{value: amount}();
        }

        uint256 before = address(c).balance;

        bool ok;
        vm.prank(depositor);
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        if (amount > 0) {
            assertTrue(ok && address(c).balance < before);
        } else {
            assertTrue(ok && address(c).balance == before);
        }
    }
}
